import hashlib
import json
import uuid
from pathlib import Path

import torch
from safetensors.torch import save_file

ROOT = Path(__file__).resolve().parent
SEED = 20260903
BATCH = 1
SEQUENCE = 16384
QUERY_HEADS = 32
KV_HEADS = 8
HEAD_DIM = 128
BLOCK_SIZE = 128
CAPACITY = 16
BLOCKS = SEQUENCE // BLOCK_SIZE
NAME = "block_sparse"


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    for directory in ("definitions", "workloads", "inputs"):
        (ROOT / directory).mkdir(parents=True, exist_ok=True)
    frozen = ROOT / "inputs/frozen.json"
    if frozen.exists():
        raise FileExistsError("Inputs are already frozen")

    # Generate FP32 normals on CPU, then round once to BF16.
    generator = torch.Generator(device="cpu").manual_seed(SEED)
    tensors = {}
    for name, heads in (("q", QUERY_HEADS), ("k", KV_HEADS), ("v", KV_HEADS)):
        tensors[name] = torch.randn(
            BATCH, heads, SEQUENCE, HEAD_DIM, generator=generator, dtype=torch.float32
        ).to(torch.bfloat16)

    # A separate seeded stream makes mask sampling independent of tensor sizes.
    mask_rng = torch.Generator(device="cpu").manual_seed(SEED)
    ids = torch.full((BATCH, QUERY_HEADS, BLOCKS, CAPACITY), -1, dtype=torch.int32)
    counts = torch.empty((BATCH, QUERY_HEADS, BLOCKS), dtype=torch.int32)
    for batch in range(BATCH):
        for head in range(QUERY_HEADS):
            for block in range(BLOCKS):
                count = min(CAPACITY, block + 1)
                previous = torch.randperm(block, generator=mask_rng)[: count - 1]
                selected = torch.cat((previous, torch.tensor([block]))).sort().values
                ids[batch, head, block, :count] = selected.to(torch.int32)
                counts[batch, head, block] = count
                assert len(set(selected.tolist())) == count
                assert selected[-1].item() == block
    tensors.update(block_ids=ids, block_counts=counts)

    path = ROOT / "inputs/block_sparse.safetensors"
    save_file(tensors, str(path), metadata={
        "seed": str(SEED),
        "klineage.strides": json.dumps({key: list(t.stride()) for key, t in tensors.items()}),
    })
    axes = {
        "B": {"type": "var"}, "S": {"type": "var"},
        "HQ": {"type": "const", "value": QUERY_HEADS},
        "HKV": {"type": "const", "value": KV_HEADS},
        "D": {"type": "const", "value": HEAD_DIM},
        "NB": {"type": "var"}, "C": {"type": "const", "value": CAPACITY},
    }
    shapes = {"q": ["B", "HQ", "S", "D"], "k": ["B", "HKV", "S", "D"],
              "v": ["B", "HKV", "S", "D"], "block_ids": ["B", "HQ", "NB", "C"],
              "block_counts": ["B", "HQ", "NB"]}
    specs = {key: {"shape": shapes[key], "dtype": str(t.dtype).removeprefix("torch."),
                   "description": f"Contiguous; element strides {list(t.stride())}."}
             for key, t in tensors.items()}
    definition = {
        "name": NAME,
        "op_type": "causal_block_sparse_attention",
        "axes": axes,
        "inputs": specs,
        "outputs": {"out": dict(specs["q"])},
        "reference": (ROOT / "reference.py").read_text(),
    }
    workload = {
        "uuid": str(uuid.uuid5(uuid.NAMESPACE_OID, digest(path))),
        "axes": {"B": BATCH, "S": SEQUENCE, "NB": BLOCKS},
        "inputs": {key: {"type": "safetensors", "path": "inputs/block_sparse.safetensors",
                         "tensor_key": key} for key in tensors},
    }
    definition_path = ROOT / f"definitions/{NAME}.json"
    workload_path = ROOT / f"workloads/{NAME}.jsonl"
    definition_path.write_text(json.dumps(definition, indent=2) + "\n")
    workload_path.write_text(json.dumps({"definition": NAME, "workload": workload}) + "\n")
    manifest = {
        "seed": SEED,
        "torch_version": torch.__version__,
        "backend": {"language": "cuda", "platform": "cuda", "device": "NVIDIA H100 PCIe", "sm": 90},
        "files": {str(p.relative_to(ROOT)): digest(p) for p in (path, definition_path, workload_path)},
        "tensors": {key: {"shape": list(t.shape), "dtype": str(t.dtype),
                          "stride": list(t.stride()), "bytes": t.numel() * t.element_size()}
                    for key, t in tensors.items()},
        "mask": {"minimum_count": int(counts.min()), "maximum_count": int(counts.max()),
                 "active_blocks": int(counts.sum()), "padding": -1, "diagonal": "included"},
    }
    frozen.write_text(json.dumps(manifest, indent=2) + "\n")
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()
