import json
import math
from pathlib import Path

import torch

from reference import run

ROOT = Path(__file__).resolve().parent
SEED = 20260903
TOLERANCE = 1e-2


def dense_example(q, k, v, ids, counts):
    # Explicit token lists and FP64 scalar dots avoid the gathered reference path.
    result = torch.empty_like(q)
    block_size = q.shape[2] // ids.shape[2]
    groups = q.shape[1] // k.shape[1]
    for head in range(q.shape[1]):
        for token in range(q.shape[2]):
            block = token // block_size
            selected = ids[0, head, block, : counts[0, head, block]].tolist()
            keys = [j for j in range(token + 1) if j // block_size in selected]
            scores = torch.tensor([
                sum(float(q[0, head, token, d]) * float(k[0, head // groups, j, d])
                    for d in range(q.shape[-1])) / math.sqrt(q.shape[-1]) for j in keys
            ], dtype=torch.float64)
            weights = torch.softmax(scores, 0)
            result[0, head, token] = sum(
                weights[i] * v[0, head // groups, j].double() for i, j in enumerate(keys)
            )
    return result


def main():
    rng = torch.Generator().manual_seed(SEED)
    q = torch.randn(1, 4, 6, 4, generator=rng).to(torch.bfloat16)
    k = torch.randn(1, 2, 6, 4, generator=rng).to(torch.bfloat16)
    v = torch.randn(1, 2, 6, 4, generator=rng).to(torch.bfloat16)
    ids = torch.tensor([[[[0, -1], [0, 1], [0, 2]],
                         [[0, -1], [0, 1], [1, 2]],
                         [[0, -1], [0, 1], [0, 2]],
                         [[0, -1], [0, 1], [1, 2]]]], dtype=torch.int32)
    counts = torch.tensor([[[1, 2, 2]] * 4], dtype=torch.int32)
    actual = run(q, k, v, ids, counts)
    expected = dense_example(q, k, v, ids, counts)
    assert actual.shape == expected.shape and actual.dtype == expected.dtype
    assert torch.allclose(actual, expected, rtol=TOLERANCE, atol=TOLERANCE)
    assert torch.equal(actual[0, :, 0], v[0, :, 0].repeat_interleave(2, 0))

    # Zero scores make the retained values' arithmetic mean hand-checkable.
    uniform = run(torch.zeros_like(q), k, v, ids, counts)
    retained = torch.tensor([0, 1, 4])
    mean = v[0, 0, retained].float().mean(0).to(v.dtype)
    assert torch.equal(uniform[0, 0, 4], mean)
    report = {"passed": True, "seed": SEED, "shape": list(q.shape),
              "max_abs_error": float((actual.float() - expected.float()).abs().max()),
              "checks": ["FP64 scalar oracle", "GQA mapping", "diagonal causality",
                         "head-specific masks", "excluded middle block", "padding ignored",
                         "first-token identity", "uniform-score retained-value mean"]}
    evidence = ROOT.parent / "baseline/evaluations"
    evidence.mkdir(parents=True, exist_ok=True)
    (evidence / "reference-example.json").write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps(report))


if __name__ == "__main__":
    main()
